/** Só as flags ativas e dentro do agendamento, no formato leve da loja. */
export async function getActiveFlagsForStorefront(shop) {
  const flags = await prisma.flag.findMany({
    where: { shop, active: true },
    orderBy: { priority: "desc" },
  });
  const now = new Date();
  return flags
    .filter((f) => !(f.startsAt && now < f.startsAt) && !(f.endsAt && now > f.endsAt))
    .map((f) => ({
      condition_type: f.conditionType,
      condition_value: f.conditionValue,
      label_text: f.labelText,
      background_color: f.backgroundColor,
      text_color: f.textColor,
      icon: f.icon,
      icon_image_url: f.iconImageUrl,
      template: f.template,
      style: normalizeStyle(f.style),
      position: f.position,
      priority: f.priority,
    }));
}

// app/routes/apps.flags.jsx: a loja chama /apps/flags no próprio domínio
const cache = new Map(); // por processo; com várias instâncias, use Redis
const CACHE_TTL_MS = 60 * 1000;

export async function loader({ request }) {
  // a Shopify assina a requisição do App Proxy; a lib valida a assinatura
  const { session } = await authenticate.public.appProxy(request);
  if (!session) return json([]);

  const { shop } = session;
  // versão das flags enviada pela loja (?v=); muda a cada salvamento
  const version = new URL(request.url).searchParams.get("v") ?? "";

  const cached = cache.get(shop);
  if (cached && cached.version === version && Date.now() - cached.at < CACHE_TTL_MS) {
    return json(cached.data);
  }

  const flags = await getActiveFlagsForStorefront(shop);
  cache.set(shop, { data: flags, version, at: Date.now() });
  return json(flags);
}

